#!/usr/bin/env python3
# luxarch:luxpm-search-mark hook v5 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Record that this session SEARCHED LuxPM, the moment the search returns.

PostToolUse(luxpm_semantic_search | luxpm_list_issues | luxpm_create_issue):
- a search (`luxpm_semantic_search`, or `luxpm_list_issues` with a `search` term) sets this session's
  marker, and its term is recorded for edit-history;
- a path search (`luxpm_list_issues(path=<file or directory>)`) sets the marker too, and the page of
  its RESULT is recorded for edit-history: each issue's key, `state:` and `labels:`, and which
  results the page shows (`Showing 1-5 (end of results)`, or `More results exist: pass offset=N`);
- an issue actually FILED (LuxPM's "Created issue" confirmation) clears the marker, so the next
  create needs a new search.

luxpm-search-before-create and edit-history read what is recorded. A record written by the search's
own PostToolUse hook is on disk before the next tool call begins, which the transcript is not.

A path search is recorded only when its `project` is this repo's (the `project:` line of the
committed `.luxpm-receipt`): a search of no project or of another one is not credited, and with no
receipt no path search is. It is recorded only when nothing else narrows it: `search`, `state`, `labels` or any
other filter would hide a hold, so such a call is no answer to "is this file held?". Its pages are
recorded only when every listed issue carries a `state:` line: a result in another shape is not
judged, and the agent is told to search by text as well. When the result shows a hold (an
on_hold issue or an open escalation that is not this worktree's own issue), an issue in progress
elsewhere (advice, never a hold), or more pages to read, the agent is told so in the same turn.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (
    STABLE_SORTS,
    WORK_ORDER_LABEL,
    Issue,
    Page,
    PathSearch,
    clear_searched,
    hold_line,
    mark_searched,
    norm_path,
    own_issue_key,
    read_event,
    record_path_page,
    record_search_term,
    repo_project,
    tree_dir,
)

_SEMANTIC = "mcp__luxpm__luxpm_semantic_search"
_LIST = "mcp__luxpm__luxpm_list_issues"
_CREATE = "mcp__luxpm__luxpm_create_issue"
_FILED = "Created issue"
# what a path search may carry beside `path` without narrowing which open issues it lists
_PLAIN = {
    "path",
    "project",
    "include_closed",
    "limit",
    "offset",
    "sort_by",
    "sort_order",
    "verbose",
}
_HEAD = re.compile(r"^- ([A-Z][A-Z0-9]{0,30}-\d{1,9}): ")
_STATE = re.compile(r"^  state: ([a-z_]{1,30})(?: \||$)")
_LABEL_SEP = " | labels: "
_WAITING = "| waiting on "
_SUMMARY = "  Summary: "
# `verbose=true` prints a close summary as this line, then each of its lines behind `_QUOTED`
_SUMMARY_BLOCK = "  Summary:"
_QUOTED = "   | "
_QUOTED_BLANK = "   |"
# the lines a listing carries outside its issues: the page line and the shortened-summary note
_FOOTER = re.compile(r"^(?:Showing \d|\d{1,4} close summar)")
_SHOWING = re.compile(r"^Showing (\d{1,7})-(\d{1,7})\b")
_MORE = "More results exist"
_NONE = "No issues found"


def _collect_text(obj: object, out: list[str]) -> None:
    """Every `text` field in an MCP content-block structure, in order."""
    if isinstance(obj, dict):
        t = obj.get("text")
        if isinstance(t, str):
            out.append(t)
        for k, v in obj.items():
            if k != "text":
                _collect_text(v, out)
    elif isinstance(obj, list):
        for v in obj:
            _collect_text(v, out)


def response_text(raw: object) -> str:
    if isinstance(raw, str):
        return raw
    parts: list[str] = []
    _collect_text(raw, parts)
    return "\n".join(parts)


def _offset(raw: object) -> int | None:
    if raw is None or raw == "":
        return 0
    try:
        n = int(str(raw))
    except ValueError:
        return None
    return n if n >= 0 else None


def _state_line(line: str, issue: Issue) -> bool:
    """Read `  state: <s> [| <priority>] [| waiting on <text>] [| labels: <a, b>]` into `issue`.
    LuxPM leaves the `| labels:` segment out for an issue with no labels. When it is there, the
    labels are what follows the LAST `| labels: `: a waiting_on is free text printed before the
    labels and can hold that string itself, so on an unlabelled issue its text reads as labels.
    A label read that way can add a hold, never lift one: a line with a waiting_on whose labels
    name the work-order label (which holds nothing) is not read. False when the line does not
    parse."""
    state = _STATE.match(line)
    if not state:
        return False
    left, names = line, []
    if _LABEL_SEP in line:
        left, labels = line.rsplit(_LABEL_SEP, 1)
        names = [x.strip() for x in labels.split(",") if x.strip()]
        if not names:
            return False
    if _WAITING in line and WORK_ORDER_LABEL in names:
        return False
    waiting = left.split(_WAITING, 1)[1].strip() if _WAITING in left else ""
    issue.update(state=state.group(1), labels=names, waiting=waiting)
    return True


def read_page(text: str, offset: int, order: str) -> tuple[Page, list[Issue]] | None:
    """The page a path search returned, or None when the result is not in the shape judged:
    each issue is its header line, one state line (naming its labels, if it has any) and optionally
    a `Summary:` line, or (under `verbose`) a bare `Summary:` line and its quoted lines; any other
    line inside an issue (a waiting_on broken over lines, a field this hook does not know) fails the
    whole page, never a pass."""
    if text.strip().startswith(_NONE):
        return (offset + 1, offset, False, order), []
    lines = text.splitlines()
    if not lines or lines[0].strip() != "Issues:":
        return None
    issues: list[Issue] = []
    page: Page | None = None
    inside = quoting = False
    for line in lines[1:]:
        head = _HEAD.match(line)
        if head:
            issues.append(
                {"key": head.group(1), "state": "", "waiting": "", "labels": []}
            )
            inside, quoting = True, False
            continue
        if not line.strip():
            inside = False
            continue
        if inside:
            if quoting and (line.startswith(_QUOTED) or line == _QUOTED_BLANK):
                continue
            if issues[-1]["state"] and line == _SUMMARY_BLOCK:
                quoting = True
                continue
            if line.startswith(_SUMMARY) and issues[-1]["state"] and not quoting:
                continue
            if issues[-1]["state"] or not _state_line(line, issues[-1]):
                return None
            continue
        shown = _SHOWING.match(line.strip())
        if shown:
            page = (int(shown.group(1)), int(shown.group(2)), _MORE in line, order)
        elif not _FOOTER.match(line.strip()):
            return None
    if page is None or any(not i["state"] for i in issues):
        return None
    return page, issues


def _context(text: str) -> None:
    out = {
        "hookSpecificOutput": {
            "hookEventName": "PostToolUse",
            "additionalContext": text,
        }
    }
    sys.stdout.write(json.dumps(out) + "\n")


def _path_search(inp: dict[str, object], response: object) -> None:
    raw = inp.get("path")
    path = norm_path(raw if isinstance(raw, str) else "")
    if not path:
        return
    narrowed = sorted(
        k for k, v in inp.items() if k not in _PLAIN and v not in (None, "", [])
    )
    if narrowed:
        _context(
            f"edit-history: this search for {path} is narrowed by {', '.join(narrowed)}, which can "
            f'hide a hold, so it does not clear the file. Run luxpm_list_issues(path="{path}", '
            "project=<this repo's project>) with no other filter."
        )
        return
    ours = repo_project(tree_dir())
    asked = str(inp.get("project") or "").strip().upper()
    if not ours or asked != ours:
        _context(
            f"edit-history: this search for {path} is "
            + (f"for project {asked}" if asked else "not scoped to a project")
            + (
                f", not this repo's {ours}, so it does not clear the file. Run "
                f'luxpm_list_issues(path="{path}", project="{ours}").'
                if ours
                else ", and this checkout has no .luxpm-receipt naming its project, so no path "
                f'search clears the file. Run luxpm_list_issues(search="{path}") and read every hit.'
            )
        )
        return
    offset = _offset(inp.get("offset"))
    sort_by, sort_order = inp.get("sort_by"), inp.get("sort_order")
    order = (
        f"{sort_by}:{sort_order}"
        if sort_by in STABLE_SORTS and sort_order in ("asc", "desc")
        else ""
    )
    read = (
        read_page(response_text(response), offset, order)
        if offset is not None
        else None
    )
    if read is None:
        _context(
            f"edit-history could not read this result for {path}, so it does not clear the file. "
            f'Run luxpm_list_issues(search="{path}") as well and read every hit.'
        )
        return
    page, issues = read
    mark_searched()
    if not record_path_page(path, page, issues):
        return
    rec = PathSearch([page], issues)
    own = own_issue_key(tree_dir())
    said: list[str] = []
    held = rec.holds(own)
    if held:
        said.append(
            f"edit-history: {path} is named by {'; '.join(hold_line(i) for i in held)}. Read "
            "each: if one holds the change you mean to make, do not make it here."
        )
    busy = rec.in_progress(own)
    if busy:
        said.append(
            f"In progress elsewhere on {path}: {', '.join(busy)}. Check them before overlapping."
        )
    if page[2]:
        fixed = (
            f'sort_by="{sort_by}", sort_order="{sort_order}"'
            if order
            else 'sort_by="sequence_id", sort_order="asc"'
        )
        said.append(
            f"edit-history: the result for {path} has more pages. Read them "
            f'(luxpm_list_issues(path="{path}", project="{ours}", {fixed}, offset={page[1]})) '
            "before changing the file"
            + (
                "."
                if order
                else ", from offset=0: a result of several pages counts only when every page "
                "is listed in that one fixed order."
            )
        )
    if said:
        _context("\n".join(said))


def main() -> int:
    ev = read_event()
    tool = str(ev.get("tool_name") or "")
    raw = ev.get("tool_input")
    inp: dict[str, object] = raw if isinstance(raw, dict) else {}
    if tool == _LIST and isinstance(inp.get("path"), str) and str(inp["path"]).strip():
        _path_search(inp, ev.get("tool_response"))
    if tool == _SEMANTIC or (tool == _LIST and str(inp.get("search") or "").strip()):
        mark_searched()
        record_search_term(str(inp.get("search") or inp.get("query") or ""))
    elif tool == _CREATE and _FILED in str(ev.get("tool_response") or ""):
        clear_searched()
    return 0


if __name__ == "__main__":
    sys.exit(main())
